import bpy
from mathutils import Vector

def zb(name):
    o = bpy.data.objects[name]
    zs = [(o.matrix_world @ v.co).z for v in o.data.vertices]
    ys = [(o.matrix_world @ v.co).y for v in o.data.vertices]
    return {'n': len(o.data.vertices), 'zmin': min(zs), 'zmax': max(zs), 'ymin': min(ys), 'ymax': max(ys), 'loc': list(o.location)}

names = ['ServeBowl','WorkBowl','Head','EyeLP','EyeLW','Noren1','ToquePuff','SignRamen']
result = {n: zb(n) for n in names if n in bpy.data.objects}
result['missing'] = [n for n in names if n not in bpy.data.objects]

import bpy
names = [n for n in bpy.data.objects.keys() if n.startswith(('Serve','Work','Steam','Welcome','Naruto','Chop'))]
out = {}
for n in sorted(names):
    o = bpy.data.objects[n]
    if o.type != 'MESH':
        continue
    zs = [(o.matrix_world @ v.co).z for v in o.data.vertices]
    out[n] = {'loc': [round(c,3) for c in o.location], 'z0': round(min(zs),3), 'z1': round(max(zs),3)}
result = out
